import { path } from '@servicenow/sdk-build-core'
import { findInput, getMergedRecordUpdates, loadTestFile, unzipInputArray } from './test-utils'
import { createTestContext } from '../../test-utils'

describe('Duration with Datapills Test Suite', () => {
    const ctx = createTestContext({ rootDir: path.resolve(__dirname, 'project') })
    beforeAll(() => ctx.initialize())
    afterEach(() => ctx.cleanup())
    describe('Duration -> Fluent to XML', () => {
        test('Duration with literal values', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'duration-datapills-example.now.ts', 'duration')

            // Verify action instances were created
            expect(merged['sys_hub_action_instance_v2']).toBeDefined()
            const actionInstances = merged['sys_hub_action_instance_v2']
            expect(actionInstances.length).toBeGreaterThan(0)

            // Find the log action with duration from flow variables
            const logActionWithVars = actionInstances.find(
                (action: any) => action.comment === 'Log with Duration using flow variable datapills'
            )
            expect(logActionWithVars).toBeDefined()

            // Parse the action inputs
            const inputsArr = unzipInputArray(logActionWithVars.values)
            const durationInput = findInput(inputsArr, 'duration_field')

            expect(durationInput).toBeDefined()
            const durationValue = durationInput.value

            // Duration with literal values should be formatted as ServiceNow duration string
            expect(durationValue).toBeDefined()
            expect(typeof durationValue).toBe('string')

            // Should be in format: '1970-01-DD HH:MM:SS' where DD, HH, MM, SS are the duration components
            // For days: 5, hours: 3, minutes: 30, seconds: 45
            // Format: '1970-01-06 03:30:45' (5 days means day 6 from epoch)
            expect(durationValue).toMatch(/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/)
        })

        test('Duration with literal values from trigger example', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'duration-datapills-example.now.ts', 'duration')

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Find the log action with duration from trigger
            const logActionWithTrigger = actionInstances.find(
                (action: any) => action.comment === 'Log with Duration using trigger datapills'
            )
            expect(logActionWithTrigger).toBeDefined()

            const inputsArr = unzipInputArray(logActionWithTrigger.values)
            const durationInput = findInput(inputsArr, 'duration_field')

            expect(durationInput).toBeDefined()
            const durationValue = durationInput.value

            // Duration should be a valid duration string
            // For days: 1, hours: 2, minutes: 30, seconds: 0
            expect(durationValue).toBeDefined()
            expect(typeof durationValue).toBe('string')
            expect(durationValue).toMatch(/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/)
        })

        test('Duration with literal values only', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'duration-datapills-example.now.ts', 'duration')

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Find the log action with duration using literal values
            const logActionWithLiterals = actionInstances.find(
                (action: any) => action.comment === 'Log with Duration using literal values'
            )
            expect(logActionWithLiterals).toBeDefined()

            const inputsArr = unzipInputArray(logActionWithLiterals.values)
            const durationInput = findInput(inputsArr, 'duration_field')

            expect(durationInput).toBeDefined()
            const durationValue = durationInput.value

            // Duration with literal values
            // For days: 2, hours: 12, minutes: 15, seconds: 45
            expect(durationValue).toBeDefined()
            expect(typeof durationValue).toBe('string')
            expect(durationValue).toMatch(/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/)
        })

        test('Duration format consistency across actions', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'duration-datapills-example.now.ts', 'duration')

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Count actions with duration fields
            const actionsWithDuration = actionInstances.filter((action: any) => {
                const inputsArr = unzipInputArray(action.values)
                return findInput(inputsArr, 'duration_field') !== undefined
            })

            expect(actionsWithDuration.length).toBeGreaterThanOrEqual(3)

            // All duration values should be consistent format
            actionsWithDuration.forEach((action: any) => {
                const inputsArr = unzipInputArray(action.values)
                const durationInput = findInput(inputsArr, 'duration_field')
                expect(durationInput?.value).toBeDefined()
                expect(typeof durationInput?.value).toBe('string')
            })
        })

        test('Duration format structure', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'duration-datapills-example.now.ts', 'duration')

            const actionInstances = merged['sys_hub_action_instance_v2']
            const firstLogAction = actionInstances.find((action: any) => action.comment?.includes('Duration'))

            const inputsArr = unzipInputArray(firstLogAction.values)
            const durationInput = findInput(inputsArr, 'duration_field')

            expect(durationInput).toBeDefined()
            const durationValue = durationInput.value

            // Duration should follow ServiceNow format or contain datapills
            expect(durationValue).toBeDefined()

            // Should either be a duration format or contain datapill markers
            const isValidDuration = durationValue.includes('{{') || /^\d{4}-\d{2}-\d{2}/.test(durationValue)
            expect(isValidDuration).toBe(true)
        })
    })

    describe('WaitForADuration with Duration', () => {
        test('WaitForADuration with literal duration values', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'duration-datapills-example.now.ts', 'duration')

            // Verify flow logic instance was created for waitForADuration
            expect(merged['sys_hub_flow_logic_instance_v2']).toBeDefined()
            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']

            // Find the waitForADuration instance
            const waitInstance = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Wait with Duration using literal values'
            )
            expect(waitInstance).toBeDefined()

            // Parse the flow logic values
            const valuesJson = unzipInputArray(waitInstance.values) as any

            // Verify duration type
            expect(valuesJson.inputs[0].value).toBe('explicit_duration')

            // Verify duration is formatted correctly
            const percentage_timer_input_datetime = valuesJson.inputs[1].name
            expect(percentage_timer_input_datetime).toBeDefined()
            // For days: 0, hours: 3, minutes: 30, seconds: 0
            expect(valuesJson.inputs[3].value).toEqual('1970-01-01 03:30:00')
        })

        test('WaitForADuration duration field structure', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'duration-datapills-example.now.ts', 'duration')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const waitInstance = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Wait with Duration using literal values'
            )

            const valuesJson = unzipInputArray(waitInstance.values) as any
            expect(valuesJson).toBeDefined()
            const inputs = valuesJson?.inputs

            // Duration should be a string with valid duration format
            expect(inputs.length).toBe(7)
            expect(inputs[0]?.value).toEqual('explicit_duration')
        })
    })

    describe('Duration - Edge Cases and Validation', () => {
        test('WaitForADuration with zero days', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'duration-datapills-example.now.ts', 'duration')

            const flowLogicInstances = merged['sys_hub_flow_logic_instance_v2']
            const waitInstance = flowLogicInstances.find(
                (instance: any) => instance.comment === 'Wait with Duration using literal values'
            )

            const valuesJson = unzipInputArray(waitInstance.values) as any

            // Duration with days: 0, seconds: 0, hours: 3, minutes: 30
            expect(valuesJson).toBeDefined()
            // expect(typeof valuesJson.duration).toBe('string')
            // expect(valuesJson.duration).toMatch(/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/)
        })

        test('Duration values are properly formatted', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'duration-datapills-example.now.ts', 'duration')

            const actionInstances = merged['sys_hub_action_instance_v2']
            const logAction = actionInstances.find(
                (action: any) => action.comment === 'Log with Duration using flow variable datapills'
            )

            const inputsArr = unzipInputArray(logAction.values)
            const durationInput = findInput(inputsArr, 'duration_field')
            const durationValue = durationInput?.value

            // Duration should be formatted as ServiceNow duration string
            expect(durationValue).toBeDefined()
            expect(typeof durationValue).toBe('string')
            expect(durationValue).toMatch(/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/)
        })

        test('Multiple actions with duration fields', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'duration-datapills-example.now.ts', 'duration')

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Count actions with duration fields
            const actionsWithDuration = actionInstances.filter((action: any) => {
                const inputsArr = unzipInputArray(action.values)
                return findInput(inputsArr, 'duration_field') !== undefined
            })

            // Should have exactly 3 actions with duration fields
            expect(actionsWithDuration.length).toBe(3)

            // Each should have valid duration
            actionsWithDuration.forEach((action: any) => {
                const inputsArr = unzipInputArray(action.values)
                const durationInput = findInput(inputsArr, 'duration_field')
                expect(durationInput?.value).toBeDefined()
                expect(typeof durationInput?.value).toBe('string')
            })
        })

        test('Flow completes with log action', async () => {
            const project = ctx.createProject()
            const merged = await getMergedRecordUpdates(project, 'duration-datapills-example.now.ts', 'duration')

            const actionInstances = merged['sys_hub_action_instance_v2']

            // Find the completion log action
            const completionLog = actionInstances.find((action: any) => {
                const inputsArr = unzipInputArray(action.values)
                const logMessage = findInput(inputsArr, 'log_message')?.value
                return logMessage?.includes('Duration with datapills test completed')
            })

            expect(completionLog).toBeDefined()
        })

        test('DEF0790325 - Duration field in wait-for-a-duration logic when transformed remains a duration shape', async () => {
            const project = ctx.createProject()
            const filename = 'sys_hub_flow_876d52461ce23a18f877c84dc8efced9'

            const xmlContent = loadTestFile(`${filename}.xml`, 'duration')
            const { changedFiles } = await project.transform({ path: `${filename}.xml`, content: xmlContent })

            expect(changedFiles).toHaveLength(1)
            expect(changedFiles[0].getName()).toBe(`${filename}.now.ts`)

            const content = changedFiles[0].getContent()

            expect(content).toContain('wfa.flowLogic.waitForADuration')

            // Validate that the duration field is a Duration object
            expect(content).toContain('duration: Duration({')

            // Validate that the duration field is not a string (starts with quotations)
            expect(content).not.toMatch(/duration:\s*['"]/)

            const durationMatch = content.match(/duration:\s*Duration\(\s*\{([^}]+)}\s*\)/)
            expect(durationMatch).toBeTruthy()

            const durationFields = durationMatch[1]
            expect(durationFields).not.toMatch(/['"]/)

            expect(content).toContain("durationType: 'explicit_duration'")
        })
    })
})
